import { Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { fetchProducts, type Product } from '../lib/api';
import ProductCard from './ProductCard';

export default function ProductGrid() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProducts()
      .then(res => {
        // API already returns newest first (ORDER BY created_at DESC)
        // Take the first 4 as "Koleksi Terbaru"
        setProducts((res.data || []).slice(0, 4));
      })
      .catch(() => setProducts([]))
      .finally(() => setLoading(false));
  }, []);

  return (
    <section className="py-12 md:py-20 px-4 md:px-6 max-w-[1440px] mx-auto" id="catalog">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 mb-8 md:mb-12">
        <div>
          <span className="text-primary font-bold tracking-widest text-xs uppercase mb-2 block">Premium Selection</span>
          <h2 className="text-3xl md:text-4xl font-extrabold tracking-tight">Koleksi Terbaru</h2>
        </div>
        <Link
          to="/catalog"
          className="text-primary-dim hover:text-primary font-bold text-sm flex items-center gap-2 transition-colors"
        >
          Lihat Semua
          <span className="material-symbols-outlined">arrow_forward</span>
        </Link>
      </div>

      {/* Loading skeletons */}
      {loading && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="bg-surface-container rounded-xl overflow-hidden animate-pulse">
              <div className="aspect-[3/4] bg-surface-container-high"></div>
              <div className="p-6 space-y-3">
                <div className="h-2 w-1/3 bg-surface-container-high rounded"></div>
                <div className="h-5 w-2/3 bg-surface-container-high rounded"></div>
                <div className="h-6 w-1/2 bg-[#00D4FF]/20 rounded"></div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Product grid */}
      {!loading && products.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
          {products.map(product => (
            <Link key={product.id} to={`/product/${product.id}`} className="block">
              <ProductCard product={product} />
            </Link>
          ))}
        </div>
      )}

      {/* Empty state */}
      {!loading && products.length === 0 && (
        <div className="text-center py-16 text-on-surface-variant">
          <span className="material-symbols-outlined text-4xl mb-3 block">inventory_2</span>
          <p className="font-semibold">Belum ada produk. Tambahkan lewat Admin Panel.</p>
        </div>
      )}
    </section>
  );
}
